@media (pointer:coarse), (max-width:900px) { #mob-controls{display:block !important} }
#mob-stick{position:fixed;bottom:34px;left:34px;width:140px;height:140px;border-radius:50%;background:rgba(0,0,0,.5);border:3px solid rgba(255,215,0,.7);pointer-events:auto;touch-action:none;z-index:6;box-shadow:0 4px 16px rgba(0,0,0,.4)}
#mob-stick::before{content:'MOVE';position:absolute;top:-22px;left:50%;transform:translateX(-50%);color:rgba(255,215,0,.85);font-size:11px;font-weight:700;letter-spacing:1px;text-shadow:0 1px 2px #000}
#mob-stick-knob{position:absolute;top:50%;left:50%;width:60px;height:60px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#ffe066,#bf8a00);transform:translate(-50%,-50%);pointer-events:none;box-shadow:0 2px 8px rgba(0,0,0,.5)}
.mob-btn{position:fixed;width:72px;height:72px;border-radius:50%;background:rgba(0,0,0,.7);border:3px solid var(--gold);color:var(--gold);font-size:24px;font-weight:700;pointer-events:auto;z-index:6;display:flex;align-items:center;justify-content:center;cursor:pointer;user-select:none;box-shadow:0 4px 16px rgba(0,0,0,.4)}

