let state = 'title';
let round = 1;
let roundClock = ROUND_LEN;
let scorePlayer = 0, scoreCpu = 0;
let knockdownsPlayer = 0, knockdownsCpu = 0;
let slowmoT = 0;
let cameraShake = 0;
let flashAmount = 0;

function makeBoxer(opts){
  const b = {
    name: opts.name,
    isPlayer: !!opts.isPlayer,
    x: opts.x,                // X coordinate on the ring (world)
    facing: opts.facing || 1, // +1 faces +X, -1 faces -X
    hp: 100, maxHp: 100,
    stamina: 100, maxStam: 100,
    color: opts.color,
    trunks: opts.trunks,
    skin: opts.skin || 0xd6a26b,
    gloveColor: opts.gloveColor,
    action: 'idle',
    actionT: 0, actionDur: 0,
    hitFrameDone: false,
    flinch: 0, bob: 0,
    aiTimer: 0, aiState: 'idle',
    aiAggression: 0.5, aiReaction: 0.4,
    rig: createBoxer3D({ trunks: opts.trunks, skin: opts.skin, gloveColor: opts.gloveColor }),
  };
  return b;
}

let player, cpu;

function resetMatch(){
  state = 'fight';
  round = 1;
  roundClock = ROUND_LEN;
  scorePlayer = 0; scoreCpu = 0;
  knockdownsPlayer = 0; knockdownsCpu = 0;
  setupRound();
  hideScreen('screen-title');
  hideScreen('screen-end');
  playBell();
}

function setupRound(){
  // Remove any existing rigs
  if (player) scene.remove(player.rig.root);
  if (cpu)    scene.remove(cpu.rig.root);
  player = makeBoxer({ name:'YOU',   isPlayer: true, x: -1.6, facing:  1, color:0x7d2424, trunks:0xcc0000, gloveColor:0xff3838, skin:0xd6a26b });
  cpu    = makeBoxer({ name:'BRUNO',                  x:  1.6, facing: -1, color:0x1f3d6e, trunks:0x0066cc, gloveColor:0x3da2ff, skin:0xc08550 });
  cpu.aiAggression = 0.45 + round*0.12;
  cpu.aiReaction = 0.35 + round*0.10;
  scene.add(player.rig.root);
  scene.add(cpu.rig.root);
  // Initial positions/rotations
  player.rig.root.position.set(player.x, FLOOR_Y, 0);
  cpu.rig.root.position.set(cpu.x, FLOOR_Y, 0);
  cpu.rig.root.rotation.y = Math.PI; // CPU faces -X
  roundClock = ROUND_LEN;
  document.getElementById('round-num').textContent = 'R' + round;
}

