//  Input
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const keys = {};
window.addEventListener('keydown', e => {
  ensureAudio();
  const k = e.key.toLowerCase();
  if (['w','a','s','d','j','k','l',' '].includes(k)) e.preventDefault();
  keys[k] = true;
});
window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });
document.querySelectorAll('#touch-controls .touch-btn[data-tk]').forEach(btn => {
  const tk = btn.dataset.tk;
  btn.addEventListener('touchstart', e => { e.preventDefault(); ensureAudio(); keys[tk] = true; });
  btn.addEventListener('touchend',   e => { e.preventDefault(); keys[tk] = false; });
  btn.addEventListener('touchcancel',e => { keys[tk] = false; });
});

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Boxer logic (same as 2D)
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function startAction(b, kind){
  if (b.hp <= 0) return;
  if (b.action === 'ko') return;
  if (b.action !== 'idle' && b.action !== 'block') return;
  if (kind in PUNCH){
    const p = PUNCH[kind];
    if (b.stamina < p.stam * 0.5) return;
    b.stamina = Math.max(0, b.stamina - p.stam);
    b.action = kind; b.actionT = 0;
    b.actionDur = p.windup + p.active + p.recover;
    b.hitFrameDone = false;
  } else if (kind === 'block'){
    b.action = 'block'; b.actionT = 0; b.actionDur = 0;
  }
}
function endAction(b){ b.action = 'idle'; b.actionT = 0; }

function takeHit(target, source, kind){
  const p = PUNCH[kind];
  const blocked = (target.action === 'block');
  let dmg = p.dmg;
  if (blocked){
    dmg = Math.round(dmg * 0.18);
    target.stamina = Math.max(0, target.stamina - p.stam * 0.6);
    playBlock();
    spawnHitText('BLOCK', target, '#9fdcff');
  } else {
    if (kind === 'uppercut') dmg += 4;
    target.flinch = 0.35;
    if (target.action !== 'ko') target.action = 'hit';
    target.actionT = 0;
    target.actionDur = p.windup + 0.05;
    // Knockback in 3D X axis
    target.x += (target.x < source.x ? -1 : 1) * p.knockback;
    playHit(kind === 'jab' ? 1 : kind === 'hook' ? 2 : 3);
    const word = kind === 'jab' ? 'POW' : kind === 'hook' ? 'BAM' : 'BOOM';
    const col  = kind === 'jab' ? '#ffd700' : kind === 'hook' ? '#ff7a00' : '#ff3838';
    spawnHitText(word, target, col);
    if (kind === 'uppercut') flashAmount = 0.32;
    cameraShake = Math.max(cameraShake, kind === 'jab' ? 0.05 : kind === 'hook' ? 0.10 : 0.18);
  }
  target.hp -= dmg;
  if (target.hp <= 0){
    target.hp = 0;
    target.action = 'ko';
    target.actionT = 0;
    target.actionDur = 1.6;
    slowmoT = 1.5;
    flashAmount = 0.45;
    if (target.isPlayer) knockdownsPlayer++; else knockdownsCpu++;
  }
}

function checkPunchHit(attacker, defender){
  if (!(attacker.action in PUNCH)) return;
  const p = PUNCH[attacker.action];
  if (attacker.actionT < p.windup || attacker.actionT > p.windup + p.active) return;
  if (attacker.hitFrameDone) return;
  const dx = defender.x - attacker.x;
  const dist = Math.abs(dx);
  if (dist > p.range) return;
  if (attacker.facing > 0 && dx < 0) return;
  if (attacker.facing < 0 && dx > 0) return;
  attacker.hitFrameDone = true;
  takeHit(defender, attacker, attacker.action);
}

function tickPlayer(b, dt){
  b.facing = (cpu.x > b.x) ? 1 : -1;
  let mx = 0;
  if (keys['a']) mx -= 1;
  if (keys['d']) mx += 1;
  if (keys['w']) mx += b.facing * 0.6;
  if (keys['s']) mx -= b.facing * 0.6;
  const speed = (b.action === 'idle' || b.action === 'block') ? 2.4 : 0.6;
  if (b.action !== 'ko' && b.action !== 'hit'){
    b.x += mx * speed * dt;
  }
  b.x = Math.max(-RING_HALF + 0.4, Math.min(RING_HALF - 0.4, b.x));
  if (b.action === 'block' && !keys[' ']) endAction(b);
  if (b.action === 'idle'){
    if (keys[' ']) startAction(b, 'block');
    else if (keys['j']) startAction(b, 'jab');
    else if (keys['k']) startAction(b, 'hook');
    else if (keys['l']) startAction(b, 'uppercut');
  }
  tickAction(b, dt);
}

function tickAction(b, dt){
  if (b.action === 'ko'){ b.actionT += dt; return; }
  if (b.action === 'hit'){
    b.actionT += dt;
    if (b.actionT >= b.actionDur) endAction(b);
    return;
  }
  if (b.action === 'block'){ b.stamina = Math.max(0, b.stamina - 4 * dt); return; }

  if (b.action in PUNCH){
    b.actionT += dt;
    if (b.actionT >= b.actionDur) endAction(b);
  }
  if (b.action === 'idle' && b.stamina < b.maxStam){
    b.stamina = Math.min(b.maxStam, b.stamina + 18 * dt);
  }
  if (b.flinch > 0) b.flinch = Math.max(0, b.flinch - dt);
}

function tickCpu(c, dt){
  c.facing = (player.x < c.x) ? -1 : 1;
  c.aiTimer -= dt;
  const dx = player.x - c.x;
  const dist = Math.abs(dx);
  const playerThreatening = (player.action === 'hook' || player.action === 'uppercut') && player.actionT < PUNCH[player.action].windup;
  if (playerThreatening && dist < 1.7 && Math.random() < c.aiReaction * dt * 60){
    if (c.action === 'idle') startAction(c, 'block');
  } else if (c.action === 'block' && (!playerThreatening || dist > 2.0)){
    endAction(c);
  }
  if (c.action === 'idle'){
    if (c.aiTimer <= 0){
      c.aiTimer = 0.3 + Math.random() * 0.6;
      if (dist > 3.0)         c.aiState = 'advance';
      else if (dist > 1.6){
        if (Math.random() < c.aiAggression) c.aiState = (Math.random() < 0.5 ? 'advance' : 'jab');
        else c.aiState = 'idle-bob';
      } else {
        if (c.stamina < 25) c.aiState = 'retreat';
        else {
          const r = Math.random();
          if (r < c.aiAggression * 0.55){
            if (Math.random() < 0.5) c.aiState = 'jab';
            else if (Math.random() < 0.6) c.aiState = 'hook';
            else c.aiState = 'uppercut';
          } else if (r < 0.85) c.aiState = 'sidestep';
          else c.aiState = 'block-tactical';
        }
      }
    }
    let cmx = 0;
    if (c.aiState === 'advance')          cmx = (dx > 0 ? 1 : -1);
    else if (c.aiState === 'retreat')     cmx = (dx > 0 ? -1 : 1);
    else if (c.aiState === 'sidestep')    cmx = (dx > 0 ? -0.3 : 0.3);
    else if (c.aiState === 'jab')         { startAction(c, 'jab'); cmx = 0; }
    else if (c.aiState === 'hook')        { startAction(c, 'hook'); cmx = 0; }
    else if (c.aiState === 'uppercut')    { startAction(c, 'uppercut'); cmx = 0; }
    else if (c.aiState === 'block-tactical'){ startAction(c, 'block'); cmx = 0; }
    c.x += cmx * 1.7 * dt;
    c.x = Math.max(-RING_HALF + 0.4, Math.min(RING_HALF - 0.4, c.x));
