// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Boxer animation â€” set arm pose per frame
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function animateBoxer(b, dt){
  const r = b.rig;
  // Position root
  r.root.position.x = b.x;
  // Rotation: facing +X = 0, facing -X = Ï€
  const targetYaw = (b.facing > 0) ? 0 : Math.PI;
  // smooth
  let dy = targetYaw - r.root.rotation.y;
  while (dy > Math.PI) dy -= Math.PI * 2;
  while (dy < -Math.PI) dy += Math.PI * 2;
  r.root.rotation.y += dy * Math.min(1, dt * 14);

  // KO fall
  if (b.action === 'ko'){
    const t = Math.min(1, b.actionT / 0.6);
    r.root.rotation.x = t * (Math.PI/2);
    r.root.position.y = -t * 0.15;
  } else {
    r.root.rotation.x = 0;
    r.root.position.y = 0;
  }

  // Idle bob
  let bobY = 0;
  if (b.action === 'idle'){
    bobY = Math.sin(performance.now() * 0.005) * 0.025;
  }
  // flinch lateral wobble
  let flinchLean = 0;
  if (b.flinch > 0){
    flinchLean = Math.sin(b.flinch * 30) * 0.04;
    r.head.rotation.z = flinchLean;
    r.torso.rotation.z = flinchLean * 0.5;
  } else {
    r.head.rotation.z *= (1 - dt * 10);
    r.torso.rotation.z *= (1 - dt * 10);
  }
  // small body bob through the torso/head
  r.head.position.y = 1.95 + bobY;
  r.torso.position.y = 1.42 + bobY;

  // Default guard pose
  r.setGuardPose();

  // Apply arm overrides per action
  const t = b.actionT;
  if (b.action === 'jab'){
    const p = PUNCH.jab;
    let ext = 0;
    if (t < p.windup) ext = (t / p.windup) * 0.2;
    else if (t < p.windup + p.active) ext = 0.2 + 0.55 * Math.min(1, (t - p.windup) / Math.max(0.001, p.active));
    else { const r2 = (t - p.windup - p.active) / p.recover; ext = 0.75 * (1 - r2); }
    // Lead arm extends along +X (forward)
    r.leadArm.shoulder.rotation.set(0, 0, 0);
    r.leadArm.shoulder.position.set(0.05, 1.55, 0.32);
    r.leadArm.armPivot.position.set(ext * 0.4, 0, 0);
    r.leadArm.armPivot.rotation.set(0, 0, 0);
  } else if (b.action === 'hook'){
    const p = PUNCH.hook;
    let swing = 0; // 0 = wound up behind, 1 = at front
    if (t < p.windup) swing = -0.4 * (t / p.windup);
    else if (t < p.windup + p.active) swing = -0.4 + 1.4 * Math.min(1, (t - p.windup) / Math.max(0.001, p.active));
    else { const r2 = (t - p.windup - p.active) / p.recover; swing = (1 - 0) - r2; if (swing < 0) swing = 0; }
    // Rear arm swings horizontally (around Y axis at shoulder)
    r.rearArm.shoulder.rotation.set(0, swing * 1.6, -0.3);
    r.rearArm.shoulder.position.set(-0.05, 1.55, -0.28);
    r.rearArm.armPivot.position.set(0.18, 0, 0);
  } else if (b.action === 'uppercut'){
    const p = PUNCH.uppercut;
    let raise = 0;
    if (t < p.windup) raise = -0.3 + (t / p.windup) * 0.1;
    else if (t < p.windup + p.active){
      const a = Math.min(1, (t - p.windup) / Math.max(0.001, p.active));
      raise = -0.2 + a * 1.3;
    } else { const r2 = (t - p.windup - p.active) / p.recover; raise = 1.1 * (1 - r2); }
    // Rear arm rises (rotate around Z axis upward)
    r.rearArm.shoulder.rotation.set(0, 0.3, raise);
    r.rearArm.shoulder.position.set(-0.05, 1.45, -0.18);
    r.rearArm.armPivot.position.set(0.25, 0, 0);
  } else if (b.action === 'block'){
    // Both arms in front of face
    r.leadArm.shoulder.rotation.set(0, 0, -1.4);
    r.leadArm.shoulder.position.set(0.20, 1.78, 0.16);
    r.leadArm.armPivot.position.set(0.0, 0, 0);
    r.rearArm.shoulder.rotation.set(0, 0, -1.4);
    r.rearArm.shoulder.position.set(0.20, 1.78, -0.16);
    r.rearArm.armPivot.position.set(0.0, 0, 0);
  } else if (b.action === 'hit'){
    // Brief arms-down flinch
    r.leadArm.shoulder.rotation.set(0, 0, -0.4);
    r.leadArm.shoulder.position.set(0.0, 1.5, 0.3);
    r.rearArm.shoulder.rotation.set(0, 0, -0.5);
    r.rearArm.shoulder.position.set(-0.08, 1.5, -0.3);
  }
}

