let lastT = performance.now();
function loop(now){
  requestAnimationFrame(loop);
  let dt = (now - lastT) / 1000;
  lastT = now;
  if (dt > 0.1) dt = 0.1;
  if (slowmoT > 0){ slowmoT -= dt; dt *= 0.32; }

  if (state === 'fight') update(dt);

  // Animate boxers (always, so KO falls finish playing)
  if (player) animateBoxer(player, dt);
  if (cpu)    animateBoxer(cpu,    dt);

  updateHitBursts(dt);
  updateHud();

  // Camera shake
  const shakeX = cameraShake > 0 ? (Math.random() - 0.5) * cameraShake : 0;
  const shakeY = cameraShake > 0 ? (Math.random() - 0.5) * cameraShake : 0;
  if (cameraShake > 0) cameraShake = Math.max(0, cameraShake - dt * 1.6);
  camera.position.set(camDefault.x + shakeX, camDefault.y + shakeY, camDefault.z);
  camera.lookAt(camLookAt);

  // Flash
  if (flashAmount > 0){
    document.getElementById('flash').style.opacity = flashAmount;
    flashAmount = Math.max(0, flashAmount - dt * 1.6);
  } else {
    document.getElementById('flash').style.opacity = 0;
  }

  renderer.render(scene, camera);
}

function update(dt){
  roundClock -= dt;
  tickPlayer(player, dt);
  tickCpu(cpu, dt);
  checkPunchHit(player, cpu);
  checkPunchHit(cpu, player);
  if (player.hp <= 0 || cpu.hp <= 0){
    state = 'roundover';
    showBanner(player.hp <= 0 ? 'YOU GOT KO\'D' : 'KNOCKOUT!');
    setTimeout(roundEnd, 1700);
  } else if (roundClock <= 0){
    roundClock = 0;
    state = 'roundover';
    showBanner('END OF ROUND ' + round);
    setTimeout(roundEnd, 1100);
  }
}

function showBanner(text){
  const b = document.getElementById('round-banner');
  b.textContent = text;
  b.classList.add('show');
  setTimeout(() => b.classList.remove('show'), 1600);
}

function roundEnd(){
  let winner = null;
  if (player.hp <= 0) winner = 'cpu';
  else if (cpu.hp <= 0) winner = 'player';
  else if (player.hp > cpu.hp) winner = 'player';
  else if (cpu.hp > player.hp) winner = 'cpu';
  if (winner === 'player') scorePlayer++;
  else if (winner === 'cpu') scoreCpu++;
  const matchOver = (round >= TOTAL_ROUNDS) || player.hp <= 0 || cpu.hp <= 0;
  if (matchOver) finishMatch();
  else { round++; setupRound(); state = 'fight'; playBell(); }
}

function finishMatch(){
  state = 'end';
  let title = 'DRAW', sub = '';
  if (player.hp <= 0)              { title = 'KNOCKED OUT'; sub = 'Round ' + round + ' Â· Bruno wins by KO'; }
  else if (cpu.hp <= 0)            { title = 'VICTORY!';    sub = 'Round ' + round + ' Â· You win by KO!'; }
  else if (scorePlayer > scoreCpu) { title = 'VICTORY!';    sub = 'You win on points Â· ' + scorePlayer + '-' + scoreCpu; }
  else if (scoreCpu > scorePlayer) { title = 'DEFEAT';      sub = 'Bruno wins on points Â· ' + scoreCpu + '-' + scorePlayer; }
  else { title = 'DRAW'; sub = 'Split decision Â· ' + scorePlayer + '-' + scoreCpu; }
  document.getElementById('end-title').textContent = title;
  document.getElementById('end-sub').textContent = sub;
  document.getElementById('end-stats').textContent =
    'Knockdowns: You ' + knockdownsCpu + ' Â· Bruno ' + knockdownsPlayer +
    '  â€¢  HP left: You ' + Math.round(player.hp) + ' Â· Bruno ' + Math.round(cpu.hp);
  showScreen('screen-end');
  playBell();
}

function showScreen(id){ document.getElementById(id).classList.add('active'); }
