function startDodge(b){
  if (b.hp <= 0 || b.action === 'ko') return;
  if (b.dodgeCooldown > 0) return;
  if (b.action !== 'idle') return;
  b.action = 'dodge';
  b.actionT = 0;
  b.actionDur = 0.38;
  b.dodgeCooldown = 0.9;
}

function takeHit(target, source, kind){
  const p = PUNCH[kind];
  const blocked = (target.action === 'block');

  // Dodge check â€” crouching slips jabs/hooks but uppercuts catch you low
  if (!blocked && target.kneesBent > 0.5 && target.action === 'dodge'){
    if (kind !== 'uppercut'){
      pushHitText(target.x, target.y - 80, 'DODGE!', '#44ff88');
      return;
    }
    // Uppercut punishes the crouch
    pushHitText(target.x, target.y - 80, 'CAUGHT!', '#ff8800');
  }

  let dmg = p.dmg;
  if (blocked){
    dmg = Math.round(dmg * 0.18);
    target.stamina = Math.max(0, target.stamina - p.stam * 0.6);
    playBlock();
    pushHitText(target.x, target.y - 100, 'BLOCK', '#9fdcff');
  } else {
    if (kind === 'uppercut') dmg += 4;
    target.flinch = 0.35;
    if (target.action !== 'ko') target.action = 'hit';
    target.actionT = 0;
    target.actionDur = p.windup + 0.05;
    target.x += (target.x < source.x ? -1 : 1) * p.knockback * (blocked ? 0.3 : 1);
    playHit(kind === 'jab' ? 1 : kind === 'hook' ? 2 : 3);
    const word = kind === 'jab' ? 'POW' : kind === 'hook' ? 'BAM' : 'BOOM';
    const col = kind === 'jab' ? '#ffd700' : kind === 'hook' ? '#ff7a00' : '#ff3838';
    pushHitText(target.x, target.y - 110, word, col);
    if (kind === 'uppercut') screenFlash = 0.12;
    screenShake = Math.max(screenShake, kind === 'jab' ? 2 : kind === 'hook' ? 4 : 7);
  }
  target.hp -= dmg;
  if (target.hp <= 0){
    target.hp = 0;
    target.action = 'ko';
    target.actionT = 0;

    ctx.moveTo(RING_LEFT, y + 1.5);
    ctx.lineTo(RING_RIGHT, y + 1.5);
    ctx.stroke();
  }
}

