// â”€â”€ Leg segment helper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Draws hipâ†’kneeâ†’foot as two thick rectangles meeting at a knee joint
function drawLegSegs(hx, hy, kx, ky, fx, fy, w, color){
  function seg(ax, ay, bx, by, hw){
    const a = Math.atan2(by - ay, bx - ax);
    const px = Math.sin(a) * hw, py = Math.cos(a) * hw;
    ctx.beginPath();
    ctx.moveTo(ax - px, ay + py);
    ctx.lineTo(bx - px, by + py);
    ctx.lineTo(bx + px, by - py);
    ctx.lineTo(ax + px, ay - py);
    ctx.closePath();
    ctx.fill();
  }
  ctx.fillStyle = color;
  seg(hx, hy, kx, ky, w / 2);       // thigh
  seg(kx, ky, fx, fy, w / 2 - 1.5); // shin (slightly thinner)
}

// â”€â”€ Boxer renderer â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function drawBoxer(b){
  const f = b.facing;
  const x = Math.round(b.x);
  const y = Math.round(b.y);
  const koProg = b.action === 'ko' ? Math.min(1, b.actionT / 0.6) : 0;
  const flinchY = b.flinch > 0 ? Math.sin(b.flinch * 30) * 2 : 0;
  const bobY = (b.action === 'idle') ? Math.sin(performance.now() * 0.005) * 2 : 0;

  const bend = b.kneesBent;
  const crouchDrop = bend * 16; // hip drops up to 16px when crouching

  // Foot X swing for stepping animation
  const stepAmt = 9;
  const leftFootDX  =  Math.sin(b.legPhase * Math.PI * 2) * stepAmt;
  const rightFootDX =  Math.sin(b.legPhase * Math.PI * 2 + Math.PI) * stepAmt;

  ctx.save();
  ctx.translate(x, y - flinchY - bobY);
  if (koProg > 0){
    ctx.translate(0, koProg * 30);
    ctx.rotate(f * koProg * 0.9);
  }
  ctx.scale(f, 1);

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,.45)';
  ctx.beginPath();
  ctx.ellipse(0, 4, 30, 6, 0, 0, Math.PI*2);
  ctx.fill();

  // â”€â”€ Legs with bent knees + stepping feet â”€â”€
  const hipY      = -38 + crouchDrop; // hip drops as boxer crouches
  const footY     = 0;                // feet always on floor
  const kneeY     = (hipY + footY) / 2;
  const leftKneeX  = -9 - bend * 13;  // knees splay outward when bent
  const rightKneeX =  9 + bend * 13;

  drawLegSegs(-9, hipY, leftKneeX, kneeY, -9 + leftFootDX, footY, 12, b.trunks);
  drawLegSegs( 9, hipY, rightKneeX, kneeY,  9 + rightFootDX, footY, 12, b.trunks);

  // Knee caps (flesh-toned dots at joint)
  ctx.fillStyle = b.skin;
  ctx.beginPath(); ctx.arc(leftKneeX, kneeY, 5, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(rightKneeX, kneeY, 5, 0, Math.PI*2); ctx.fill();

  // Boots (move with feet)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(-9 + leftFootDX  - 11, footY - 5, 22, 5);
  ctx.fillRect( 9 + rightFootDX - 11, footY - 5, 22, 5);

  // Trunks waistband (descends with crouch)
  ctx.fillStyle = '#ffd700';
  ctx.fillRect(-22, hipY - 6, 44, 8);

  // Torso (relative to hip)
  ctx.fillStyle = b.skin;
  ctx.fillRect(-22, hipY - 50, 44, 50);
  // Chest shadow
  ctx.fillStyle = 'rgba(0,0,0,.18)';
  ctx.fillRect(-22, hipY - 50, 44, 6);

  // Head + face (relative to hip)
  const headCY = hipY - 68;

  let leadAng = 0, rearAng = 0;
  let leadY = 0, rearY = 0;

  if (action === 'jab'){
    const p = PUNCH.jab;
    if (t < p.windup) { leadExt = (t / p.windup) * 30; }
    else if (t < p.windup + p.active) { leadExt = 30 + 20; }
    else { const r = (t - p.windup - p.active) / p.recover; leadExt = 50 * (1 - r); }
  } else if (action === 'hook'){
    const p = PUNCH.hook;
    if (t < p.windup){ rearAng = -((t / p.windup) * 0.8); rearExt = 8; }
    else if (t < p.windup + p.active){ rearAng = 0.4; rearExt = 50; }
    else { const r = (t - p.windup - p.active) / p.recover; rearAng = 0.4 * (1 - r); rearExt = 50 * (1 - r); }
  } else if (action === 'uppercut'){
    const p = PUNCH.uppercut;
    if (t < p.windup){ rearY = -(t / p.windup) * 18; rearExt = 5; }
    else if (t < p.windup + p.active){ rearY = -28; rearExt = 38; }
    else { const r = (t - p.windup - p.active) / p.recover; rearY = -28 * (1 - r); rearExt = 38 * (1 - r); }
  } else if (action === 'block'){
    leadExt = 6; rearExt = 6;
    leadY = -16; rearY = -16;
    leadAng = 0.4; rearAng = -0.4;
  } else if (action === 'hit'){
    leadExt = -4; rearExt = -4;
    leadY = 6; rearY = 6;
  }

  // Rear arm (back arm) â€” drawn first so lead arm is in front
  ctx.save();
  ctx.translate(-10, -75 + rearY + crouchDrop);
  ctx.rotate(rearAng);
  ctx.fillStyle = '#d6a26b';
  ctx.fillRect(0, -6, 14 + rearExt, 12);
  ctx.fillStyle = glove;
  ctx.beginPath();
  ctx.arc(14 + rearExt, 0, 10, 0, Math.PI*2);
  ctx.fill();
  ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.restore();

  // Lead arm
  ctx.save();
  ctx.translate(8, -78 + leadY + crouchDrop);
  ctx.rotate(leadAng);
  ctx.fillStyle = '#d6a26b';
  ctx.fillRect(0, -6, 14 + leadExt, 12);
  ctx.fillStyle = glove;
  ctx.beginPath();
  ctx.arc(14 + leadExt, 0, 11, 0, Math.PI*2);
  ctx.fill();
  ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke();
  // Glove highlight
  ctx.fillStyle = 'rgba(255,255,255,.35)';
  ctx.beginPath();
  ctx.arc(14 + leadExt - 3, -3, 3, 0, Math.PI*2);
  ctx.fill();
  ctx.restore();
}

