    bicep.scale.set(1, 1.4, 1);
    shoulder.add(bicep);
    // Elbow / forearm pivot
    const forearmRot = new THREE.Group();
    forearmRot.position.y = -0.32;
    shoulder.add(forearmRot);
    const elbow = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 6), skinMat);
    forearmRot.add(elbow);
    const forearm = new THREE.Mesh(
      new THREE.CylinderGeometry(0.07, 0.058, 0.26, 10),
      skinMat
    );
    forearm.position.y = -0.13;
    forearmRot.add(forearm);

    // â”€â”€â”€ BOXING GLOVE â”€â”€â”€
    const gloveGroup = new THREE.Group();
    gloveGroup.position.y = -0.30;
    forearmRot.add(gloveGroup);
    // Wrist cuff (white) â€” the tube of laces around the wrist
    const cuff = new THREE.Mesh(
      new THREE.CylinderGeometry(0.085, 0.085, 0.10, 14),
      cuffMat
    );
    cuff.position.y = 0.10;
    gloveGroup.add(cuff);
    // Tiny lace marks across the cuff
    for (let i = 0; i < 4; i++){
      const lace = new THREE.Mesh(
        new THREE.BoxGeometry(0.018, 0.006, 0.005),
        laceMat
      );
      lace.position.set(0.083, 0.13 - i * 0.018, 0);
      gloveGroup.add(lace);
      const lace2 = lace.clone();
      lace2.position.x = -0.083;
      gloveGroup.add(lace2);
    }
    // Main fist â€” a squashed sphere
    const fist = new THREE.Mesh(
      new THREE.SphereGeometry(0.155, 14, 10),
      gloveMat
    );
    fist.scale.set(1.0, 0.95, 1.05);
    fist.position.y = -0.05;
    gloveGroup.add(fist);
    // Knuckle ridge (slim box across the front of the fist)
    const knuckle = new THREE.Mesh(
      new THREE.BoxGeometry(0.02, 0.10, 0.20),
      gloveMat
    );
    knuckle.position.set(0.14, -0.04, 0);
    gloveGroup.add(knuckle);
    // Brand stripe â€” a band across the back-of-hand area
    const brand = new THREE.Mesh(
      new THREE.BoxGeometry(0.02, 0.04, 0.22),
      stripeMat
    );
    brand.position.set(-0.13, -0.01, 0);
    gloveGroup.add(brand);
    // Thumb (visible bump on the inside of the fist toward the body)
    const thumb = new THREE.Mesh(new THREE.SphereGeometry(0.055, 10, 8), gloveMat);
    thumb.scale.set(0.9, 1.2, 1.0);
    thumb.position.set(0.06, 0.02, -side * 0.12);
    gloveGroup.add(thumb);

    root.add(shoulder);
    return { shoulder, forearmRot, glove: gloveGroup };
  }
  const armL = buildArm(-1);
  const armR = buildArm(+1);

  // â”€â”€â”€ Default guard pose â”€â”€â”€
  function setGuardPose(){
    armL.shoulder.rotation.set(-0.4, 0, 1.45);
    armL.forearmRot.rotation.set(0, 0, 1.30);
    armR.shoulder.rotation.set( 0.4, 0, 1.45);
    armR.forearmRot.rotation.set(0, 0, 1.30);
  }
  setGuardPose();

  // â”€â”€â”€ Stun stars (hidden until triggered) â”€â”€â”€
  const stunGroup = new THREE.Group();
  stunGroup.position.y = 2.15;
  stunGroup.visible = false;
  torso.add(stunGroup);
  const starColors = [0xfff44a, 0xffd700, 0xffe066];
  const stars = [];
  for (let i = 0; i < 3; i++){
    const s = new THREE.Mesh(
      new THREE.SphereGeometry(0.045, 8, 6),
      new THREE.MeshBasicMaterial({ color: starColors[i] })
    );
    stars.push(s);
    stunGroup.add(s);
  }

  // Shadow
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.5, 18),
    new THREE.MeshBasicMaterial({ color: 0x000, transparent: true, opacity: 0.55 })
  );
  shadow.rotation.x = -Math.PI/2;
  shadow.position.y = 0.012;
  root.add(shadow);

  return {
    root, torso, headGroup, neck, chest,
    armL, armR, legL, legR,
    setGuardPose,
    stunGroup, stars,
  };
}

// Generic per-arm pose helper.
function setArmPose(armSide, pose){
  if (pose.shoulderRot) armSide.shoulder.rotation.set(pose.shoulderRot[0], pose.shoulderRot[1], pose.shoulderRot[2]);
  if (pose.forearmRot)  armSide.forearmRot.rotation.set(pose.forearmRot[0], pose.forearmRot[1], pose.forearmRot[2]);
  if (pose.offset)      armSide.shoulder.position.set(pose.offset[0], pose.offset[1], pose.offset[2]);
}

