//  Boxer animation
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const _v3 = new THREE.Vector3();

function animateBoxer(b, dt){
  const r = b.rig;
  // Position root from b.pos
  r.root.position.x = b.pos.x;
  r.root.position.z = b.pos.z;

  // Smoothly turn to targetYaw
  let dy = b.targetYaw - b.yaw;
  while (dy > Math.PI) dy -= Math.PI * 2;
  while (dy < -Math.PI) dy += Math.PI * 2;
  b.yaw += dy * Math.min(1, dt * 10);
  r.root.rotation.y = b.yaw;

  // KO fall
  if (b.action === 'ko'){
    if (!b.koStaggered){
      // brief stagger lasting ~0.25s before topple â€” root.position.x wobble
      const staggerT = Math.min(1, b.actionT / 0.25);
      r.root.position.x += Math.sin(b.actionT * 60) * 0.08 * (1 - staggerT);
      if (b.actionT > 0.25) b.koStaggered = true;
    }
    const t = Math.min(1, Math.max(0, (b.actionT - 0.25)) / 0.6);
    r.root.rotation.x = t * (Math.PI/2);
    r.root.position.y = -t * 0.15;
  } else {
    r.root.rotation.x = 0;
    r.root.position.y = 0;
  }

  // Idle breathing & weight shift
  const tNow = performance.now() * 0.001;
  let breath = 0;
  let lateralShift = 0;
  if (b.action === 'idle' && b.hp > 0){
    breath = Math.sin(tNow * 2.2) * 0.025;
    lateralShift = Math.sin(tNow * 1.4) * 0.012;
  }
  r.chest.scale.y = 1.0 + breath * 0.4;
  r.torso.position.x = lateralShift;

  // Stun sway
  if (b.stunned){
    r.torso.position.x += Math.sin(tNow * 6) * 0.06;
    r.torso.rotation.z = Math.sin(tNow * 6) * 0.10;
    r.stunGroup.visible = true;
    for (let i = 0; i < r.stars.length; i++){
      const a = tNow * 1.2 + i * (Math.PI*2/3);
      r.stars[i].position.set(Math.cos(a) * 0.22, Math.sin(tNow * 4 + i) * 0.04, Math.sin(a) * 0.22);
    }
  } else {
    r.stunGroup.visible = false;
    if (b.action !== 'hit') r.torso.rotation.z *= (1 - dt * 8);
  }

  // Lean: forward when advancing (player W key / cpu advance), back when retreat
  let targetLeanX = 0;
  if (b.action === 'idle'){
    if (b.isPlayer){
      if (keys['w']) targetLeanX = 0.10;
      else if (keys['s']) targetLeanX = -0.10;
    } else {
      if (b.aiState === 'advance') targetLeanX = 0.08;
      else if (b.aiState === 'retreat') targetLeanX = -0.10;
    }
  }
  if (b.action in PUNCH) targetLeanX = 0.18; // lean into punches
  // Apply lean as torso rotation around its local Z (forward axis) â€” actually lean is rotation around side-axis (X).
  // We lean forward â†’ rotate torso around its local Z by negative? In our model X is the forward axis; lean forward = tilt around Z (side).
  r.torso.rotation.x = (r.torso.rotation.x || 0) + (targetLeanX - (r.torso.rotation.x || 0)) * Math.min(1, dt * 6);

  // Hip counter-rotate slightly during punches
  // (we don't have hip pivot â€” fake it on legs)
  let hipTwist = 0;
  if (b.action in PUNCH){
    const p = PUNCH[b.action];
    const tp = b.actionT / Math.max(0.001, b.actionDur);
    hipTwist = Math.sin(tp * Math.PI) * 0.18 * (b.activeArm === 'lead' ? 1 : -1);
  }
  r.legL.rotation.y = hipTwist * 0.6;
  r.legR.rotation.y = hipTwist * 0.6;

  // Head tracking â€” subtle look toward opponent
  const opp = b.isPlayer ? cpu : player;
  if (opp){
    _v3.subVectors(opp.pos, b.pos);
    // local angle relative to body forward
    const localAngle = Math.atan2(-_v3.z, _v3.x) - b.yaw;
    let la = localAngle;
    while (la > Math.PI) la -= Math.PI*2;
    while (la < -Math.PI) la += Math.PI*2;
    r.headGroup.rotation.y = la * 0.35;
  }

  // Flinch â€” head jerk in hit direction
  if (b.flinch > 0 && b.action !== 'ko'){
    const t = b.flinch;
    // First 0.15s: head jerks; recoil afterwards.
    const jerk = Math.min(1, (0.35 - t) / 0.15);
    const recoil = Math.max(0, 1 - jerk);
    r.headGroup.rotation.z = (-b.flinchDir) * (jerk * 0.4 + recoil * 0.15);
    r.neck.rotation.z = (-b.flinchDir) * 0.12 * (jerk + recoil*0.5);
  } else {
    r.headGroup.rotation.z *= (1 - dt * 10);
    r.neck.rotation.z = (r.neck.rotation.z || 0) * (1 - dt * 10);
  }

  // Default guard pose
  r.setGuardPose();

  // Per-punch arm animation
  if (b.action in PUNCH){
    const kind = b.action;
    const p = PUNCH[kind];
    const tt = b.actionT / Math.max(0.001, b.actionDur);
    const phase =
      (b.actionT < p.windup) ? (b.actionT / p.windup) :                                                 // 0..1 windup
      (b.actionT < p.windup + p.active) ? (1 + (b.actionT - p.windup) / Math.max(0.001, p.active)) :    // 1..2 active
      (2 + (b.actionT - p.windup - p.active) / Math.max(0.001, p.recover));                              // 2..3 recover

    animatePunch(b, kind, phase);
  } else if (b.action === 'block'){
    setArmPose(r.armL, { shoulderRot:[-0.2, 0, 1.55], forearmRot:[0, 0.4, 1.55] });
    setArmPose(r.armR, { shoulderRot:[ 0.2, 0, 1.55], forearmRot:[0,-0.4, 1.55] });
  } else if (b.action === 'hit'){
    setArmPose(r.armL, { shoulderRot:[-0.2, 0, 1.20], forearmRot:[0, 0, 1.10] });
    setArmPose(r.armR, { shoulderRot:[ 0.2, 0, 1.20], forearmRot:[0, 0, 1.10] });
  }
}

// Drive an arm by punch family + phase (0..3).
function animatePunch(b, kind, phase){
  const r = b.rig;
  const arm = (b.activeArm === 'lead') ? r.armL : r.armR;
  const otherArm = (b.activeArm === 'lead') ? r.armR : r.armL;
  // Other arm stays in guard (already set by setGuardPose above).
  const sign = (b.activeArm === 'lead') ? -1 : 1; // L arm = -z, R arm = +z

  // ext: 0 fully retracted, 1 fully extended.  Built from phase.
  const ext = (phase < 1) ? (phase * 0.25) :
              (phase < 2) ? (0.25 + 0.75 * (phase - 1)) :
              Math.max(0, 1 - (phase - 2));

  // Default starting rotations (each punch overrides).
  let shoulderX = -0.4 + sign * 0.0;
  let shoulderY = 0;

  // Default starting rotations (each punch overrides).
  let shoulderX = -0.4 + sign * 0.0;
  let shoulderY = 0;
  let shoulderZ = 1.45;
  let forearmX  = 0;
  let forearmY  = 0;
  let forearmZ  = 1.30;

  switch (kind){
    case 'jab':
    case 'straight':
    case 'cross': {
      // Straight punch â€” shoulder swings forward (around Y), forearm extends.
      shoulderZ = 1.45 - ext * 1.45;          // arm comes down/out
      shoulderY = -sign * (0.2 + ext * 0.7);  // rotate arm forward
      shoulderX = -0.4 + ext * 0.55;
      forearmZ  = 1.30 - ext * 1.20;
      break;
    }
    case 'hook':
    case 'checkHook': {
      // Hook â€” arm parallel to ground, swings around Y.
      shoulderZ = 1.45 - ext * 0.85;
      shoulderY = -sign * (0.6 + ext * 1.4);
      shoulderX = -0.2 + ext * 0.4;
      forearmZ  = 1.30 - ext * 0.55;
      break;
    }
    case 'uppercut': {
      shoulderZ = 1.45 - ext * 1.65;          // drive up
      shoulderX = -0.7 + ext * 1.0;
      shoulderY = -sign * (0.1 + ext * 0.4);
      forearmZ  = 1.30 - ext * 0.95;
      forearmX  = ext * 0.3;
      break;
    }
    case 'overhand': {
      shoulderZ = 1.45 - ext * 1.05;
      shoulderY = -sign * (0.4 + ext * 1.0);
      shoulderX = -0.9 + ext * 0.5;            // big arc over the top
      forearmZ  = 1.30 - ext * 0.85;
      break;
    }
    case 'bodyShot': {
      shoulderZ = 1.45 - ext * 0.95;
      shoulderY = -sign * (0.3 + ext * 0.7);
      shoulderX = -0.1 - ext * 0.2;            // aim down
      forearmZ  = 1.30 - ext * 1.05;
      break;
    }
    case 'liverShot': {
      shoulderZ = 1.45 - ext * 0.95;
      shoulderY = -sign * (0.2 + ext * 0.6);
      shoulderX = -0.05 - ext * 0.30;
      forearmZ  = 1.30 - ext * 1.10;
      break;
    }
    case 'shovelHook': {
      // Mid-arc between hook & uppercut
      shoulderZ = 1.45 - ext * 1.10;
      shoulderY = -sign * (0.5 + ext * 1.1);
      shoulderX = -0.5 + ext * 0.8;
      forearmZ  = 1.30 - ext * 0.85;
      break;
    }
    case 'corkscrew': {
      shoulderZ = 1.45 - ext * 1.20;
      shoulderY = -sign * (0.3 + ext * 0.85);
      shoulderX = -0.3 + ext * 0.55;
      forearmZ  = 1.30 - ext * 1.20;
      forearmY  = sign * ext * 0.9;            // twisting in
      break;
    }
    case 'haymaker': {
      shoulderZ = 1.45 - ext * 1.0;
      shoulderY = -sign * (0.9 + ext * 1.6);
      shoulderX = -0.7 + ext * 0.6;
      forearmZ  = 1.30 - ext * 0.4;
      break;
    }
  }
  arm.shoulder.rotation.set(shoulderX, shoulderY, shoulderZ);
  arm.forearmRot.rotation.set(forearmX, forearmY, forearmZ);
}

